import sys, importlib

# Import the versioned squishtest extension (e.g. squishtest_310) when available
major = sys.version_info.major
minor = sys.version_info.minor
candidates = [f'squishtest_{major}{minor}', f'squishtest_{major}', 'squishtest_310']
for name in candidates:
    try:
        mod = importlib.import_module(name)
        # Replace this package entry with the extension module
        sys.modules[__name__] = mod
        break
    except Exception:
        continue
else:
    # leave as namespace package if no binary found
    raise ImportError(f"Could not load a squishtest binary for Python {major}.{minor}")
